import React from 'react';

export function Badge({ label, tone = 'neutral' }: { label: string; tone?: 'success' | 'info' | 'warning' | 'danger' | 'neutral' }) {
  const color = tone === 'success' ? '{{token:colors.accent.success}}' : tone === 'danger' ? '{{token:colors.accent.danger}}' : tone === 'warning' ? '{{token:colors.accent.warning}}' : tone === 'info' ? '{{token:colors.accent.primary}}' : '{{token:colors.text.secondary}}';
  return (
    <span role="status" style={{
      display: 'inline-flex', alignItems: 'center', gap: '6px',
      padding: '2px 10px', borderRadius: '999px',
      background: '{{token:colors.glass.tint}}',
      border: `1px solid ${color}`,
      color, fontSize: '{{token:typography.scale.xs}}', fontWeight: 600,
    }}>
      <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: color }} />
      {label}
    </span>
  );
}

